import type { WorksheetSnapshot } from '../../../shared/types';
import { cellKey } from './coordinates';

/**
 * Value a cell shows on screen, looked up by 0-based coordinates.
 *
 * Issue #3 decision D-A8 (contract increment A-3): the grid renderer and the
 * CSV export share this single seam, so "grid shows a calculated result while
 * the export writes the formula text" cannot happen. Sub-issue C replaces the
 * implementation of `worksheetDisplayValues` with its formula engine; this
 * module's identity is the interim, pre-C behaviour (formula cells show their
 * raw text).
 */
export type CellDisplayValue = (row: number, col: number) => string;

/** Identity seam: a cell shows exactly the raw text stored for it. */
export function worksheetDisplayValues(worksheet: WorksheetSnapshot): CellDisplayValue {
  const raw = new Map<string, string>();
  for (const [row, col, value] of worksheet.cells) {
    raw.set(cellKey(row, col), value);
  }
  return (row: number, col: number) => raw.get(cellKey(row, col)) ?? '';
}

/**
 * A1-range parsing, serialisation and the single structural shift helper
 * consumed by validation rules, filters and pivot source ranges.
 *
 * The same coordinate-mapping layer is reused by the formula-reference rewrite
 * that sub-issue C owns; this module only implements the range-level view
 * because that is what B persists. See Issue #4 comment #35 (D-B3):
 *
 * - Insert at the new block's first index `p`, `count` slots: `p <= r1` shifts
 *   the whole range down; `r1 < p <= r2` expands the range by `count`
 *   (an insertion inside a region stays inside it); `p > r2` changes nothing.
 * - Delete at `d`: `d < r1` shifts the whole range up; `r1 <= d <= r2`
 *   shrinks the range by one with `r1` fixed (`r2 -= 1`, so data that was below
 *   the deleted slot stays covered); a range that collapses (`r1 > r2`,
 *   i.e. exactly the deleted single row/column) is removed.
 *
 * Parsing is deliberately lenient: any expression this module cannot parse is
 * returned unchanged (`changed: false`) so an unknown stored format is never
 * corrupted by a structure operation.
 */

/** @typedef {{ r1: number, c1: number, r2: number, c2: number }} Rect */
/** @typedef {{ range: string, changed: boolean }} ShiftResult */
/** @typedef {'row' | 'column'} Axis */

const A1_RANGE = /^\$?([A-Za-z]+)\$?([1-9][0-9]*)(?::\$?([A-Za-z]+)\$?([1-9][0-9]*))?$/;

/**
 * Column index (0-based) to spreadsheet letters: 0 -> "A", 25 -> "Z", 26 -> "AA".
 *
 * @param {number} col
 * @returns {string}
 */
export function columnLabel(col) {
  let value = col + 1;
  let label = '';
  while (value > 0) {
    const remainder = (value - 1) % 26;
    label = String.fromCharCode(65 + remainder) + label;
    value = Math.floor((value - 1) / 26);
  }
  return label;
}

/**
 * Spreadsheet letters to a 0-based column index: "A" -> 0, "AA" -> 26.
 *
 * @param {string} letters
 * @returns {number}
 */
export function columnIndex(letters) {
  let col = 0;
  for (const character of letters.toUpperCase()) {
    col = col * 26 + (character.charCodeAt(0) - 64);
  }
  return col - 1;
}

/**
 * Parse an A1-style range (`"B2"`, `"B2:B10"`, `"$B$2:$D$10"`).
 *
 * @param {string} text
 * @returns {Rect | null}
 */
export function parseA1Range(text) {
  if (typeof text !== 'string') return null;
  const match = A1_RANGE.exec(text.trim());
  if (!match) return null;
  const c1 = columnIndex(match[1]);
  const r1 = Number.parseInt(match[2], 10) - 1;
  const c2 = match[3] === undefined ? c1 : columnIndex(match[3]);
  const r2 = match[4] === undefined ? r1 : Number.parseInt(match[4], 10) - 1;
  return {
    r1: Math.min(r1, r2),
    c1: Math.min(c1, c2),
    r2: Math.max(r1, r2),
    c2: Math.max(c1, c2),
  };
}

/**
 * Serialise a rectangle back to A1 notation. A 1x1 rectangle serialises to a
 * single reference (`"B2"`), everything else to `"B2:D10"`.
 *
 * @param {Rect} rect
 * @returns {string}
 */
export function formatA1Range(rect) {
  const start = `${columnLabel(rect.c1)}${rect.r1 + 1}`;
  if (rect.r1 === rect.r2 && rect.c1 === rect.c2) return start;
  return `${start}:${columnLabel(rect.c2)}${rect.r2 + 1}`;
}

/**
 * @param {Rect} rect
 * @param {Axis} axis
 * @param {number} at
 * @param {number} count
 * @returns {{ rect: Rect, changed: boolean }}
 */
function applyInsert(rect, axis, at, count) {
  const loKey = axis === 'row' ? 'r1' : 'c1';
  const hiKey = axis === 'row' ? 'r2' : 'c2';
  /** @type {Rect} */
  const next = { ...rect };
  if (at <= rect[loKey]) {
    next[loKey] += count;
    next[hiKey] += count;
    return { rect: next, changed: true };
  }
  if (at <= rect[hiKey]) {
    next[hiKey] += count;
    return { rect: next, changed: true };
  }
  return { rect: next, changed: false };
}

/**
 * @param {Rect} rect
 * @param {Axis} axis
 * @param {number} at
 * @returns {{ rect: Rect, changed: boolean } | null} `null` = collapsed, remove.
 */
function applyDelete(rect, axis, at) {
  const loKey = axis === 'row' ? 'r1' : 'c1';
  const hiKey = axis === 'row' ? 'r2' : 'c2';
  /** @type {Rect} */
  const next = { ...rect };
  if (at < rect[loKey]) {
    next[loKey] -= 1;
    next[hiKey] -= 1;
    return { rect: next, changed: true };
  }
  if (at <= rect[hiKey]) {
    next[hiKey] -= 1;
    if (next[loKey] > next[hiKey]) return null;
    return { rect: next, changed: true };
  }
  return { rect: next, changed: false };
}

/**
 * Shift a stored range for an insertion of `count` slots at index `at`.
 * Returns the original text untouched when it cannot be parsed.
 *
 * @param {string} range
 * @param {Axis} axis
 * @param {number} at
 * @param {number} count
 * @returns {ShiftResult}
 */
export function shiftRangeOnInsert(range, axis, at, count) {
  const rect = parseA1Range(range);
  if (!rect) return { range, changed: false };
  const { rect: next, changed } = applyInsert(rect, axis, at, count);
  return { range: changed ? formatA1Range(next) : range, changed };
}

/**
 * Shift a stored range for a deletion at index `at`.
 *
 * @param {string} range
 * @param {Axis} axis
 * @param {number} at
 * @returns {{ range: string | null, changed: boolean }} `range === null` = remove.
 */
export function shiftRangeOnDelete(range, axis, at) {
  const rect = parseA1Range(range);
  if (!rect) return { range, changed: false };
  const result = applyDelete(rect, axis, at);
  if (result === null) return { range: null, changed: true };
  return { range: result.changed ? formatA1Range(result.rect) : range, changed: result.changed };
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import type {
  CellChange,
  CellCoord,
  CellEntry,
  SelectionRect,
  WorkbookSnapshot,
  WorksheetSnapshot,
} from '../../../shared/types';
import { api } from '../api/client';
import { worksheetDisplayValues } from '../lib/cellDisplay';
import { cellKey, toCoordinate } from '../lib/coordinates';
import { messageOf } from '../lib/errors';
import { lastUpdatedText } from '../lib/format';
import { A1_SELECTION, sameSelection } from '../lib/selection';
import { ErrorBanner } from './ErrorBanner';
import { FormulaBar } from './FormulaBar';
import { Grid } from './Grid';
import { WorkbookToolbar } from './WorkbookToolbar';
import { WorksheetTabs } from './WorksheetTabs';

const LAST_UPDATED_LABEL_ID = 'workbook-last-updated';

/**
 * `/workbook/:id` editor shell: header, toolbar placeholder, name box +
 * formula bar, ARIA grid, worksheet tab bar. Cell edits and confirmed
 * selections are written through the contract endpoints and survive a refresh.
 */
export function WorkbookEditor() {
  const { id = '' } = useParams<{ id: string }>();
  const [snapshot, setSnapshot] = useState<WorkbookSnapshot | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [selectionByWorksheet, setSelectionByWorksheet] = useState<Record<string, SelectionRect>>(
    {},
  );
  const [editing, setEditing] = useState<CellCoord | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setLoadError(null);
    api
      .getWorkbook(id)
      .then((loaded) => {
        if (cancelled) return;
        setSnapshot(loaded);
        setSelectionByWorksheet(
          Object.fromEntries(
            loaded.worksheets.map((worksheet) => [
              worksheet.id,
              worksheet.lastSelection ?? A1_SELECTION,
            ]),
          ),
        );
        setLoading(false);
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setLoadError(messageOf(error));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id]);

  const worksheets = snapshot?.worksheets ?? [];
  const activeWorksheet =
    worksheets.find((worksheet) => worksheet.isActive) ?? worksheets[0] ?? null;
  const activeWorksheetId = activeWorksheet?.id ?? '';
  const selection = selectionByWorksheet[activeWorksheetId] ?? A1_SELECTION;

  const cells = useMemo(() => {
    const map = new Map<string, string>();
    for (const [row, col, raw] of activeWorksheet?.cells ?? []) {
      map.set(cellKey(row, col), raw);
    }
    return map;
  }, [activeWorksheet]);

  /**
   * Worksheet-level writes answer with the full workbook snapshot (B-1); the
   * response is the single fact source, including the server-shifted selection
   * after a structure operation. Local selections for other worksheets survive
   * so switching tabs keeps their in-session state.
   */
  const applySnapshot = useCallback((next: WorkbookSnapshot) => {
    setSnapshot(next);
    setSelectionByWorksheet((previous) => {
      const merged = { ...previous };
      for (const worksheet of next.worksheets) {
        if (worksheet.lastSelection) merged[worksheet.id] = worksheet.lastSelection;
        else if (!merged[worksheet.id]) merged[worksheet.id] = A1_SELECTION;
      }
      return merged;
    });
  }, []);

  /** Run a worksheet-level mutation and adopt its snapshot response. */
  const runWorkbookAction = useCallback(
    async (action: () => Promise<WorkbookSnapshot>) => {
      setEditing(null);
      try {
        applySnapshot(await action());
        setErrorMessage(null);
      } catch (error: unknown) {
        setErrorMessage(messageOf(error));
      }
    },
    [applySnapshot],
  );

  // Single display-value seam (D-A8): the grid and the CSV export read the same
  // function, so sub-issue C only has to replace `worksheetDisplayValues`.
  const displayValue = useMemo(
    () => (activeWorksheet ? worksheetDisplayValues(activeWorksheet) : () => ''),
    [activeWorksheet],
  );

  // Refs keep the memoized grid callbacks stable while still reading the
  // latest worksheet/cell state.
  const activeWorksheetIdRef = useRef(activeWorksheetId);
  activeWorksheetIdRef.current = activeWorksheetId;
  const worksheetsRef = useRef<WorksheetSnapshot[]>(worksheets);
  worksheetsRef.current = worksheets;
  const cellsRef = useRef(cells);
  cellsRef.current = cells;

  const applyCellLocally = useCallback((worksheetId: string, changes: CellChange[]) => {
    setSnapshot((previous) => {
      if (!previous) return previous;
      return {
        ...previous,
        worksheets: previous.worksheets.map((worksheet) => {
          if (worksheet.id !== worksheetId) return worksheet;
          const map = new Map<string, string>();
          for (const [row, col, raw] of worksheet.cells) {
            map.set(cellKey(row, col), raw);
          }
          for (const change of changes) {
            const key = cellKey(change.row, change.col);
            if (change.raw === '') map.delete(key);
            else map.set(key, change.raw);
          }
          const cellsAfter: CellEntry[] = [...map.entries()].map(([key, raw]) => {
            const [row, col] = key.split(':').map(Number);
            return [row, col, raw];
          });
          return { ...worksheet, cells: cellsAfter };
        }),
      };
    });
  }, []);

  const commitCell = useCallback(
    async (coord: CellCoord, raw: string) => {
      setEditing(null);
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      const key = cellKey(coord.row, coord.col);
      const previousValue = cellsRef.current.get(key) ?? '';
      if (previousValue === raw) return;

      applyCellLocally(worksheetId, [{ row: coord.row, col: coord.col, raw }]);
      try {
        const result = await api.putCells(id, worksheetId, [
          { row: coord.row, col: coord.col, raw },
        ]);
        setSnapshot((previous) => (previous ? { ...previous, updatedAt: result.updatedAt } : previous));
        setErrorMessage(null);
      } catch (error: unknown) {
        applyCellLocally(worksheetId, [{ row: coord.row, col: coord.col, raw: previousValue }]);
        setErrorMessage(messageOf(error));
      }
    },
    [id, applyCellLocally],
  );

  const handleSelectionChange = useCallback(
    (next: SelectionRect, persist: boolean) => {
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      setSelectionByWorksheet((previous) => {
        const current = previous[worksheetId];
        if (current && sameSelection(current, next)) return previous;
        return { ...previous, [worksheetId]: next };
      });
      if (persist) {
        api.putSelection(id, worksheetId, next).catch((error: unknown) => {
          setErrorMessage(messageOf(error));
        });
      }
    },
    [id],
  );

  const handleSelectWorksheet = useCallback(
    async (worksheetId: string) => {
      setEditing(null);
      const target = worksheetsRef.current.find((worksheet) => worksheet.id === worksheetId);
      if (!target || target.isActive) return;
      const previousActiveId =
        worksheetsRef.current.find((worksheet) => worksheet.isActive)?.id ?? worksheetId;
      const markActive = (isActiveId: string) => {
        setSnapshot((previous) =>
          previous
            ? {
                ...previous,
                worksheets: previous.worksheets.map((worksheet) => ({
                  ...worksheet,
                  isActive: worksheet.id === isActiveId,
                })),
              }
            : previous,
        );
      };
      markActive(worksheetId);
      try {
        // PATCH now answers with the full snapshot (B-1): adopting it keeps the
        // grid, structure, selection and formula bar on the target worksheet.
        applySnapshot(await api.patchWorksheet(id, worksheetId, { isActive: true }));
        setErrorMessage(null);
      } catch (error: unknown) {
        markActive(previousActiveId);
        setErrorMessage(messageOf(error));
      }
    },
    [id, applySnapshot],
  );

  const handleAddWorksheet = useCallback(() => {
    void runWorkbookAction(() => api.createWorksheet(id));
  }, [id, runWorkbookAction]);

  const handleRenameWorksheet = useCallback(
    async (worksheetId: string, name: string) => {
      // Rejections propagate to the rename dialog, which shows the exact
      // server message and keeps the worksheet name unchanged.
      applySnapshot(await api.patchWorksheet(id, worksheetId, { name }));
      setErrorMessage(null);
    },
    [id, applySnapshot],
  );

  const handleDeleteWorksheet = useCallback(
    (worksheetId: string) => runWorkbookAction(() => api.deleteWorksheet(id, worksheetId)),
    [id, runWorkbookAction],
  );

  const handleInsertRow = useCallback(
    (index: number, side: 'above' | 'below') => {
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      void runWorkbookAction(() => api.insertRows(id, worksheetId, { index, count: 1, side }));
    },
    [id, runWorkbookAction],
  );

  const handleDeleteRow = useCallback(
    (index: number) => {
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      void runWorkbookAction(() => api.deleteRow(id, worksheetId, index));
    },
    [id, runWorkbookAction],
  );

  const handleInsertColumn = useCallback(
    (index: number, side: 'left' | 'right') => {
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      void runWorkbookAction(() => api.insertColumns(id, worksheetId, { index, count: 1, side }));
    },
    [id, runWorkbookAction],
  );

  const handleDeleteColumn = useCallback(
    (index: number) => {
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      void runWorkbookAction(() => api.deleteColumn(id, worksheetId, index));
    },
    [id, runWorkbookAction],
  );

  const handleRenamed = useCallback((name: string, updatedAt: string) => {
    setSnapshot((previous) => (previous ? { ...previous, name, updatedAt } : previous));
  }, []);

  const handleStartEdit = useCallback((coord: CellCoord) => {
    setEditing({ row: coord.row, col: coord.col });
  }, []);

  const handleCommitEdit = useCallback(
    (coord: CellCoord, raw: string) => {
      void commitCell(coord, raw);
    },
    [commitCell],
  );

  const handleCancelEdit = useCallback(() => {
    setEditing(null);
  }, []);

  if (loading) {
    return <div className="p-8 text-sm text-sheet-muted">Loading workbook…</div>;
  }

  if (loadError || !snapshot || !activeWorksheet) {
    return (
      <div className="mx-auto max-w-2xl p-8">
        <ErrorBanner message={loadError ?? 'Workbook not found'} />
        <Link to="/" className="text-sm text-sheet-accent underline">
          Back to workbooks
        </Link>
      </div>
    );
  }

  const anchorCell: CellCoord = { row: selection.r1, col: selection.c1 };
  const selectedRaw = cells.get(cellKey(anchorCell.row, anchorCell.col)) ?? '';

  return (
    <div className="flex h-screen flex-col bg-white">
      <header className="flex flex-wrap items-baseline gap-x-4 gap-y-1 border-b-1 border-sheet-border px-3 py-2">
        <h1 className="text-lg font-medium text-sheet-text">{snapshot.name}</h1>
        <p id={LAST_UPDATED_LABEL_ID} className="text-xs text-sheet-muted">
          {lastUpdatedText(snapshot.updatedAt)}
        </p>
      </header>

      {/* Toolbar: workbook lifecycle controls; follow-up sub-issues append here. */}
      <div
        role="toolbar"
        aria-label="Toolbar"
        className="flex h-9 items-center gap-1 border-b-1 border-sheet-border bg-sheet-header px-2"
      >
        <WorkbookToolbar
          workbookId={id}
          workbookName={snapshot.name}
          worksheet={activeWorksheet}
          displayValue={displayValue}
          onRenamed={handleRenamed}
        />
      </div>

      <FormulaBar
        coordinate={toCoordinate(anchorCell.row, anchorCell.col)}
        value={selectedRaw}
        onCommit={(value) => {
          void commitCell(anchorCell, value);
        }}
      />

      <ErrorBanner message={errorMessage} onDismiss={() => setErrorMessage(null)} />

      <div
        id="worksheet-grid-panel"
        role="tabpanel"
        aria-labelledby={`worksheet-tab-${activeWorksheetId}`}
        className="min-h-0 flex-1"
      >
        <Grid
          rowCount={activeWorksheet.rowCount}
          colCount={activeWorksheet.colCount}
          cells={cells}
          displayValue={displayValue}
          selection={selection}
          editing={editing}
          onSelectionChange={handleSelectionChange}
          onStartEdit={handleStartEdit}
          onCommitEdit={handleCommitEdit}
          onCancelEdit={handleCancelEdit}
          onInsertRow={handleInsertRow}
          onDeleteRow={handleDeleteRow}
          onInsertColumn={handleInsertColumn}
          onDeleteColumn={handleDeleteColumn}
        />
      </div>

      <WorksheetTabs
        worksheets={worksheets}
        activeWorksheetId={activeWorksheetId}
        onSelect={(worksheetId) => {
          void handleSelectWorksheet(worksheetId);
        }}
        onAdd={handleAddWorksheet}
        onRename={handleRenameWorksheet}
        onDelete={handleDeleteWorksheet}
        onError={setErrorMessage}
      />
    </div>
  );
}

import { describe, expect, it } from 'vitest';
import type { WorksheetSnapshot } from '../../../shared/types';
import { worksheetDisplayValues } from './cellDisplay';

function sheet(cells: [number, number, string][]): WorksheetSnapshot {
  return {
    id: 'ws-1',
    name: 'Sheet1',
    position: 0,
    isActive: true,
    rowCount: 6,
    colCount: 26,
    minRows: 0,
    minCols: 0,
    cells,
    lastSelection: null,
    validations: [],
    filters: [],
    pivots: [],
  };
}

/**
 * D-A8 / contract increment A-3: interim identity seam. Sub-issue C replaces the
 * implementation; these assertions describe the pre-C behaviour the acceptance
 * suite pins in the meantime (a formula cell shows and exports its raw text).
 */
describe('worksheetDisplayValues', () => {
  it('returns the raw text for populated cells', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, 'Region'], [1, 1, '1200']]));
    expect(display(0, 0)).toBe('Region');
    expect(display(1, 1)).toBe('1200');
  });

  it('returns an empty string for cells that have no stored value', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, 'Region']]));
    expect(display(5, 25)).toBe('');
    expect(display(0, 1)).toBe('');
  });

  it('returns the raw formula text before sub-issue C lands', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, '=1+1']]));
    expect(display(0, 0)).toBe('=1+1');
  });
});

/** A1-style coordinate helpers. Rows and columns are 0-based everywhere. */

/**
 * Column index to spreadsheet label: 0 -> "A", 25 -> "Z", 26 -> "AA".
 */
export function columnLabel(col: number): string {
  let value = col + 1;
  let label = '';
  while (value > 0) {
    const remainder = (value - 1) % 26;
    label = String.fromCharCode(65 + remainder) + label;
    value = Math.floor((value - 1) / 26);
  }
  return label;
}

/** `(0, 0)` -> `"A1"`; this is the accessible name of every grid cell. */
export function toCoordinate(row: number, col: number): string {
  return `${columnLabel(col)}${row + 1}`;
}

/** Stable map key for sparse cell storage. */
export function cellKey(row: number, col: number): string {
  return `${row}:${col}`;
}

/** `"B3"` -> `{row: 2, col: 1}`, or null when the reference is malformed. */
export function parseCoordinate(reference: string): { row: number; col: number } | null {
  const match = /^([A-Za-z]+)([1-9][0-9]*)$/.exec(reference.trim());
  if (!match) return null;
  const letters = match[1].toUpperCase();
  let col = 0;
  for (const character of letters) {
    col = col * 26 + (character.charCodeAt(0) - 64);
  }
  return { row: Number.parseInt(match[2], 10) - 1, col: col - 1 };
}

