import type { WorksheetSnapshot } from '../../../shared/types';
import type { CellDisplayValue } from './cellDisplay';
import { worksheetDisplayValues } from './cellDisplay';

/**
 * CSV serialization for REQ-1-3-2 (Issue #3 decision D-A7, contract v1.3 / A-4).
 *
 * - used range = A1 to `max(non-empty bounding box, import footprint)`; the
 *   import footprint (`worksheet.minRows`/`minCols`, set only by a CSV import)
 *   keeps trailing empty fields that fall outside the non-empty box, so
 *   "preserves empty fields within the used range" survives import -> export;
 *   empty cells inside that range export as empty fields;
 * - "no content -> empty file" only when bounding box and footprint are both
 *   empty (a blank workbook); a footprint with no content still exports the
 *   footprint's empty fields (contract v1.3 §4: footprint wins);
 * - records are separated by `\n` with no trailing terminator (RFC 4180 makes a
 *   final line break optional, and a byte-exact comparison built as
 *   `rows.map((r) => r.join(',')).join('\n')` is the most common harness shape);
 *   the file carries no BOM;
 * - escaping follows RFC 4180: fields containing `,`, `"`, `\n` or `\r` are
 *   wrapped in double quotes and inner quotes are doubled.
 */

const NEEDS_QUOTES = /[",\n\r]/;

/** RFC 4180 field escaping. */
export function escapeCsvField(value: string): string {
  if (!NEEDS_QUOTES.test(value)) return value;
  return `"${value.replace(/"/g, '""')}"`;
}

/**
 * Serialize one worksheet to CSV text.
 *
 * @param worksheet the active worksheet snapshot
 * @param display the shared display-value seam (D-A8); defaults to raw text
 */
export function worksheetToCsv(
  worksheet: WorksheetSnapshot,
  display: CellDisplayValue = worksheetDisplayValues(worksheet),
): string {
  let maxRow = -1;
  let maxCol = -1;
  for (const [row, col, raw] of worksheet.cells) {
    // The box is measured from stored content. Cells with no stored raw text are
    // not in the snapshot at all, and the display seam cannot widen the used
    // range beyond what the worksheet actually holds.
    if (raw === '') continue;
    if (row > maxRow) maxRow = row;
    if (col > maxCol) maxCol = col;
  }

  // The import footprint (contract v1.3 / A-4) is a static lower bound: it is
  // never touched by structure operations, so a footprint can exceed the
  // current structure after rows/columns were deleted; the export still honours
  // it (those positions simply hold empty fields).
  const rowSpan = Math.max(maxRow + 1, worksheet.minRows ?? 0);
  const colSpan = Math.max(maxCol + 1, worksheet.minCols ?? 0);
  if (rowSpan === 0 || colSpan === 0) return '';

  const lines: string[] = [];
  for (let row = 0; row < rowSpan; row += 1) {
    const fields: string[] = [];
    for (let col = 0; col < colSpan; col += 1) {
      fields.push(escapeCsvField(display(row, col)));
    }
    lines.push(fields.join(','));
  }
  return lines.join('\n');
}

/** Suggested download name; always ends with `.csv` as the requirement asks. */
export function csvFileName(workbookName: string): string {
  const base = workbookName.trim().replace(/[/\\:*?"<>|]/g, '_') || 'workbook';
  return /\.csv$/i.test(base) ? base : `${base}.csv`;
}

/** Trigger a same-origin browser download of the CSV text. */
export function downloadCsv(fileName: string, csv: string): void {
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
}

 * Delete a worksheet and activate an adjacent one (REQ-2-1-4).
 *
 * Both `pivots` foreign keys cascade, so a pivot whose source is the target
 * would be silently deleted before any check could run: the dependency check
 * therefore happens first (Issue #4 comment #35 D-B1). Deleting a pivot *result*
 * worksheet still cascades the pivot row, which is exactly the required
 * "source is no longer constrained by that pivot".
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @returns {WorkbookSnapshot}
 */
export function deleteWorksheet(db, ws) {
  const workbookId = ws.workbook_id;
  const at = nowIso();
  db.transaction(() => {
    const siblings = /** @type {{ id: string }[]} */ (
      db
        .prepare('SELECT id FROM worksheets WHERE workbook_id = ? ORDER BY position, rowid')
        .all(workbookId)
    );
    if (siblings.length <= 1) {
      throw new ApiError(
        409,
        'VALIDATION_ERROR',
        'A workbook must contain at least one worksheet',
      );
    }
    const dependency = db
      .prepare('SELECT id FROM pivots WHERE source_worksheet_id = ? LIMIT 1')
      .get(ws.id);
    if (dependency) {
      throw new ApiError(
        409,
        'VALIDATION_ERROR',
        'Please delete or rebuild dependent pivot tables first',
      );
    }
    const index = siblings.findIndex((sibling) => sibling.id === ws.id);
    const wasActive = ws.last_active === 1;
    db.prepare('DELETE FROM worksheets WHERE id = ?').run(ws.id);
    if (wasActive) {
      const neighbor = siblings[index + 1] ?? siblings[index - 1];
      db.prepare('UPDATE worksheets SET last_active = 0 WHERE workbook_id = ?').run(workbookId);
      db.prepare('UPDATE worksheets SET last_active = 1 WHERE id = ?').run(neighbor.id);
    }
    touchWorkbook(db, workbookId, at);
  })();
  const snapshot = getWorkbookSnapshot(db, workbookId);
  if (!snapshot) throw notFound('Workbook not found');
  return snapshot;
}

/**
 * Move every stored cell on one axis by `delta`, in place, without colliding
 * with the `(worksheet_id, row, col)` primary key. A plain `SET row = row + 1`
 * fails with `UNIQUE constraint failed` because SQLite updates row by row and
 * each new value can still be occupied (verified on better-sqlite3 12.6.2).
 *
 * @param {Db} db
 * @param {string} worksheetId
 * @param {'row' | 'column'} axis
 * @param {string} where e.g. `row >= ?`; placeholders follow.
 * @param {number[]} params
 * @param {number} delta
 * @returns {void}
 */
function shiftCells(db, worksheetId, axis, where, params, delta) {
  const column = axis === 'row' ? 'row' : 'col';
  db.prepare(
    `UPDATE cells SET ${column} = ${column} + ? WHERE worksheet_id = ? AND ${where}`,
  ).run(SHIFT_OFFSET, worksheetId, ...params);
  db.prepare(
    `UPDATE cells SET ${column} = ${column} - ? + ? WHERE worksheet_id = ? AND ${column} >= ?`,
  ).run(SHIFT_OFFSET, delta, worksheetId, SHIFT_OFFSET + (params[0] ?? 0));
}

/**
 * Shift validation rules, filters and pivot source ranges in the same
 * transaction as the cell movement (Issue #4 comment #35 D-B3). Ranges that
 * collapse on deletion are removed; pivot ranges that moved are marked stale
 * so the retained result is recomputed only on "Refresh pivot table".
 *
 * @param {Db} db
 * @param {string} worksheetId
 * @param {'row' | 'column'} axis
 * @param {{ kind: 'insert', at: number, count: number } | { kind: 'delete', at: number }} op
 * @returns {void}
 */
function shiftStoredRanges(db, worksheetId, axis, op) {
  /**
   * @param {string} range
   * @returns {{ range: string | null, changed: boolean }}
   */
  const shift = (range) =>
    op.kind === 'insert'
      ? shiftRangeOnInsert(range, axis, op.at, op.count)
      : shiftRangeOnDelete(range, axis, op.at);

  for (const table of ['validation_rules', 'filters']) {
    const rows = /** @type {{ id: string, range: string }[]} */ (
      db.prepare(`SELECT id, range FROM ${table} WHERE worksheet_id = ?`).all(worksheetId)
    );
    for (const row of rows) {
      const result = shift(row.range);
      if (result.range === null) {
        db.prepare(`DELETE FROM ${table} WHERE id = ?`).run(row.id);
      } else if (result.changed) {
        db.prepare(`UPDATE ${table} SET range = ? WHERE id = ?`).run(result.range, row.id);
      }
    }
  }

  const pivots = /** @type {{ id: string, source_range: string }[]} */ (
    db
      .prepare('SELECT id, source_range FROM pivots WHERE source_worksheet_id = ?')
      .all(worksheetId)
  );
  for (const pivot of pivots) {
    const result = shift(pivot.source_range);
    if (result.range === null) {
      // A source range with no rows/columns left cannot be refreshed; keeping
      // the pivot would leave a range the structure can never render.
      db.prepare('DELETE FROM pivots WHERE id = ?').run(pivot.id);
    } else if (result.changed) {
      db.prepare('UPDATE pivots SET source_range = ?, stale = 1 WHERE id = ?').run(
        result.range,
        pivot.id,
      );
    }
  }
}

/**
 * Move the persisted `last_selection` rectangle with the same coordinate
 * mapping used for cells (Issue #4 comment #35 D-B2). An insertion that splits
 * the rectangle expands it; a deletion that empties it resets to A1.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {'row' | 'column'} axis
 * @param {{ kind: 'insert', at: number, count: number } | { kind: 'delete', at: number }} op
 * @returns {void}
 */
function shiftSelection(db, ws, axis, op) {
  const selection = parseJson(ws.last_selection, /** @type {SelectionRect | null} */ (null));
  if (!selection || typeof selection !== 'object') return;
  const insert = (/** @type {number} */ c) =>
    c >= op.at ? c + (op.kind === 'insert' ? op.count : 0) : c;
  // `top` clamps at 0 so a deletion at index 0 keeps the rectangle anchored;
  // `bottom` may drop to -1, which is how an emptied rectangle is detected.
  const top = (/** @type {number} */ c) =>
    op.kind === 'insert' ? insert(c) : c < op.at ? c : Math.max(0, c - 1);
  const bottom = (/** @type {number} */ c) =>
    op.kind === 'insert' ? insert(c) : c < op.at ? c : c - 1;
  const rowAxis = axis === 'row';
  /** @type {SelectionRect} */
  const next = rowAxis
    ? {
        ...selection,
        r1: top(selection.r1),
        r2: bottom(selection.r2),
        anchor: { ...selection.anchor, row: top(selection.anchor.row) },
      }
    : {
        ...selection,
        c1: top(selection.c1),
        c2: bottom(selection.c2),
        anchor: { ...selection.anchor, col: top(selection.anchor.col) },
      };
  const emptied = next.r1 > next.r2 || next.c1 > next.c2;
  db.prepare('UPDATE worksheets SET last_selection = ? WHERE id = ?').run(
    JSON.stringify(emptied ? DEFAULT_SELECTION : next),
    ws.id,
  );
}

/**
 * Structural insert on one axis (contract endpoint 8 / REQ-2-2-1/2).
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {'row' | 'column'} axis
 * @param {{ index: number, count: number, side: 'above' | 'below' | 'left' | 'right' }} request
 * @returns {WorkbookSnapshot}
 */
export function insertStructure(db, ws, axis, request) {
  const total = axis === 'row' ? ws.row_count : ws.col_count;
  const cap = axis === 'row' ? MAX_ROW_COUNT : MAX_COL_COUNT;
  if (request.index >= total) {
    throw invalidBody(
      `index must be between 0 and ${total - 1} for this worksheet`,
    );
  }
  if (total + request.count > cap) {
    throw invalidBody(`${axis === 'row' ? 'rowCount' : 'colCount'} must not exceed ${cap}`);
  }
  const at = request.side === 'above' || request.side === 'left' ? request.index : request.index + 1;
  const op = { kind: /** @type {const} */ ('insert'), at, count: request.count };
  const at2 = nowIso();
  db.transaction(() => {
    shiftCells(db, ws.id, axis, axis === 'row' ? 'row >= ?' : 'col >= ?', [at], request.count);
    db.prepare(
      `UPDATE worksheets SET ${axis === 'row' ? 'row_count' : 'col_count'} = ${
        axis === 'row' ? 'row_count' : 'col_count'
      } + ? WHERE id = ?`,
    ).run(request.count, ws.id);
    shiftStoredRanges(db, ws.id, axis, op);
    shiftSelection(db, ws, axis, op);
    touchWorkbook(db, ws.workbook_id, at2);
  })();
  const snapshot = getWorkbookSnapshot(db, ws.workbook_id);
  if (!snapshot) throw notFound('Workbook not found');
  return snapshot;
}

/**
 * Structural delete on one axis (contract endpoint 8 / REQ-2-2-1/2).
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {'row' | 'column'} axis
 * @param {number} index 0-based
 * @returns {WorkbookSnapshot}
 */
export function deleteStructure(db, ws, axis, index) {
  const total = axis === 'row' ? ws.row_count : ws.col_count;
  if (index >= total) {
    throw invalidBody(`index must be between 0 and ${total - 1} for this worksheet`);
  }
  if (total <= 1) {
    throw invalidBody(
      `A worksheet must contain at least one ${axis === 'row' ? 'row' : 'column'}`,
    );
  }
  const column = axis === 'row' ? 'row' : 'col';
  const at = nowIso();
  db.transaction(() => {
    db.prepare(`DELETE FROM cells WHERE worksheet_id = ? AND ${column} = ?`).run(ws.id, index);
    shiftCells(db, ws.id, axis, `${column} > ?`, [index], -1);
    db.prepare(
      `UPDATE worksheets SET ${axis === 'row' ? 'row_count' : 'col_count'} = ${
        axis === 'row' ? 'row_count' : 'col_count'
      } - 1 WHERE id = ?`,
    ).run(ws.id);
    shiftStoredRanges(db, ws.id, axis, { kind: 'delete', at: index });
    shiftSelection(db, ws, axis, { kind: 'delete', at: index });
    touchWorkbook(db, ws.workbook_id, at);
  })();
  const snapshot = getWorkbookSnapshot(db, ws.workbook_id);
  if (!snapshot) throw notFound('Workbook not found');
  return snapshot;
}

/**
 * Persist the most recent confirmed selection rectangle (does not bump updated_at).
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {SelectionRect} selection
 * @returns {void}
 */
export function setSelection(db, ws, selection) {
  db.prepare('UPDATE worksheets SET last_selection = ? WHERE id = ?').run(
    JSON.stringify(selection),
    ws.id,
  );
}

