/**
 * A1-notation primitives shared by the backend structure endpoints and the
 * formula engine (sub-issue C, Issue #5 decision D-C1/D-C7).
 *
 * This module was migrated verbatim from `backend/src/ranges.js` (sub-issue B,
 * Issue #4 comment #35 D-B3) so that both consumers map coordinates through a
 * single implementation: `backend/src/ranges.js` re-exports the public names
 * and keeps its behaviour byte-for-byte.
 *
 * Two views of the same coordinate mapping:
 *
 * - **range view** (`shiftRangeOnInsert` / `shiftRangeOnDelete`) formats the
 *   result with {@link formatA1Range}, which strips `$` markers, collapses a
 *   1x1 rectangle to a single reference and uppercases the column letters. It
 *   is what B persists for validation rules, filters and pivot source ranges.
 * - **rect view** (`shiftRectOnInsert` / `shiftRectOnDelete`) returns the
 *   mapped rectangle without formatting, so the formula engine can re-emit a
 *   reference preserving the user's `$` markers, `:` separator and letter case
 *   (Issue #5 decision D-C4).
 *
 * Mapping rules (Issue #4 comment #35 D-B3):
 *
 * - Insert at the new block's first index `p`, `count` slots: `p <= r1` shifts
 *   the whole range; `r1 < p <= r2` expands the range by `count` (an insertion
 *   inside a region stays inside it); `p > r2` changes nothing.
 * - Delete at `d`: `d < r1` shifts the whole range; `r1 <= d <= r2` shrinks it
 *   by one with `r1` fixed (`r2 -= 1`); a range that collapses (`r1 > r2`,
 *   i.e. exactly the deleted single row/column) is reported as `null`.
 *
 * Parsing is deliberately lenient: any expression this module cannot parse is
 * returned unchanged (`changed: false`) so an unknown stored format is never
 * corrupted by a structure operation.
 */

/** @typedef {{ r1: number, c1: number, r2: number, c2: number }} Rect */
/** @typedef {'row' | 'column'} Axis */
/** @typedef {{ range: string, changed: boolean }} ShiftResult */

const A1_RANGE = /^\$?([A-Za-z]+)\$?([1-9][0-9]*)(?::\$?([A-Za-z]+)\$?([1-9][0-9]*))?$/;

/**
 * Column index (0-based) to spreadsheet letters: 0 -> "A", 25 -> "Z", 26 -> "AA".
 *
 * @param {number} col
 * @returns {string}
 */
export function columnLabel(col) {
  let value = col + 1;
  let label = '';
  while (value > 0) {
    const remainder = (value - 1) % 26;
    label = String.fromCharCode(65 + remainder) + label;
    value = Math.floor((value - 1) / 26);
  }
  return label;
}

/**
 * Spreadsheet letters to a 0-based column index: "A" -> 0, "AA" -> 26.
 *
 * @param {string} letters
 * @returns {number}
 */
export function columnIndex(letters) {
  let col = 0;
  for (const character of letters.toUpperCase()) {
    col = col * 26 + (character.charCodeAt(0) - 64);
  }
  return col - 1;
}

/**
 * Parse an A1-style range (`"B2"`, `"B2:B10"`, `"$B$2:$D$10"`).
 *
 * @param {string} text
 * @returns {Rect | null}
 */
export function parseA1Range(text) {
  if (typeof text !== 'string') return null;
  const match = A1_RANGE.exec(text.trim());
  if (!match) return null;
  const c1 = columnIndex(match[1]);
  const r1 = Number.parseInt(match[2], 10) - 1;
  const c2 = match[3] === undefined ? c1 : columnIndex(match[3]);
  const r2 = match[4] === undefined ? r1 : Number.parseInt(match[4], 10) - 1;
  return {
    r1: Math.min(r1, r2),
    c1: Math.min(c1, c2),
    r2: Math.max(r1, r2),
    c2: Math.max(c1, c2),
  };
}

/**
 * Serialise a rectangle back to A1 notation. A 1x1 rectangle serialises to a
 * single reference (`"B2"`), everything else to `"B2:D10"`.
 *
 * @param {Rect} rect
 * @returns {string}
 */
export function formatA1Range(rect) {
  const start = `${columnLabel(rect.c1)}${rect.r1 + 1}`;
  if (rect.r1 === rect.r2 && rect.c1 === rect.c2) return start;
  return `${start}:${columnLabel(rect.c2)}${rect.r2 + 1}`;
}

/**
 * Map a rectangle through the insert rule, returning the mapped rectangle and
 * whether anything moved. This is the shared primitive the formula rewrite uses
 * (the range view below formats its result).
 *
 * @param {Rect} rect
 * @param {Axis} axis
 * @param {number} at
 * @param {number} count
 * @returns {{ rect: Rect, changed: boolean }}
 */
export function shiftRectOnInsert(rect, axis, at, count) {
  const loKey = axis === 'row' ? 'r1' : 'c1';
  const hiKey = axis === 'row' ? 'r2' : 'c2';
  /** @type {Rect} */
  const next = { ...rect };
  if (at <= rect[loKey]) {
    next[loKey] += count;
    next[hiKey] += count;
    return { rect: next, changed: true };
  }
  if (at <= rect[hiKey]) {
    next[hiKey] += count;
    return { rect: next, changed: true };
  }
  return { rect: next, changed: false };
}

/**
 * Map a rectangle through the delete rule. `null` means the rectangle collapsed
 * (it was exactly the deleted slot) and can no longer be represented.
 *
 * @param {Rect} rect
 * @param {Axis} axis
 * @param {number} at
 * @returns {{ rect: Rect, changed: boolean } | null}
 */
export function shiftRectOnDelete(rect, axis, at) {
  const loKey = axis === 'row' ? 'r1' : 'c1';
  const hiKey = axis === 'row' ? 'r2' : 'c2';
  /** @type {Rect} */
  const next = { ...rect };
  if (at < rect[loKey]) {
    next[loKey] -= 1;
    next[hiKey] -= 1;
    return { rect: next, changed: true };
  }
  if (at <= rect[hiKey]) {
    next[hiKey] -= 1;
    if (next[loKey] > next[hiKey]) return null;
    return { rect: next, changed: true };
  }
  return { rect: next, changed: false };
}

/**
 * Shift a stored range for an insertion of `count` slots at index `at`.
 * Returns the original text untouched when it cannot be parsed.
 *
 * @param {string} range
 * @param {Axis} axis
 * @param {number} at
 * @param {number} count
 * @returns {ShiftResult}
 */
export function shiftRangeOnInsert(range, axis, at, count) {
  const rect = parseA1Range(range);
  if (!rect) return { range, changed: false };
  const { rect: next, changed } = shiftRectOnInsert(rect, axis, at, count);
  return { range: changed ? formatA1Range(next) : range, changed };
}

/**
 * Shift a stored range for a deletion at index `at`.
 *
 * @param {string} range
 * @param {Axis} axis
 * @param {number} at
 * @returns {{ range: string | null, changed: boolean }} `range === null` = remove.
 */
export function shiftRangeOnDelete(range, axis, at) {
  const rect = parseA1Range(range);
  if (!rect) return { range, changed: false };
  const result = shiftRectOnDelete(rect, axis, at);
  if (result === null) return { range: null, changed: true };
  return { range: result.changed ? formatA1Range(result.rect) : range, changed: result.changed };
}

