        t.ref = ref.part;
        tokens.push(t);
        i = ref.end;
        continue;
      }
      const func = FUNC_HEAD.exec(body.slice(i));
      if (func) {
        const t = token('func', i, i + func[1].length);
        t.name = func[1]; t.upper = func[1].toUpperCase();
        tokens.push(t);
        i += func[1].length;
