/**
 * Spreadsheet formula engine: tokenizer, recursive-descent parser, memoized
 * dependency evaluation and reference rewriting.
 *
 * Sub-issue C of the spreadsheet workspace (Issue #5, decisions D-C1…D-C13).
 * This is the single implementation shared by both sides of the application:
 *
 * - the frontend reaches it through `frontend/src/lib/formula.ts`, which the
 *   display-value seam (`cellDisplay.ts`) and the copy/paste work (sub-issue D)
 *   import from;
 * - the backend imports `shared/formula.js` directly so a structural row/column
 *   insert or delete can rewrite stored formula text in the same transaction
 *   (decision D-C9).
 *
 * Supported grammar (`=` prefix required):
 *
 *   expr    := term (('+' | '-') term)*
 *   term    := unary (('*' | '/') unary)*
 *   unary   := '-' unary | primary
 *   primary := number | reference | range | call | '(' expr ')' | '#REF!'
 *   call    := NAME '(' expr (',' expr)* ')'
 *
 * with `NAME` case-insensitive in {SUM, AVERAGE, COUNT, MIN, MAX}. References
 * are same-sheet A1 coordinates with optional `$` markers; ranges are `A1:B2`.
 * `#REF!` is a first-class token so rewritten formulas (`=#REF!+A1`,
 * `=SUM(#REF!)`) stay parseable. Cross-sheet references are not supported.
 *
 * Error values and their precedence (Issue #5 decision D-C2):
 *
 *   1. tokenizer failure                       -> #ERROR!
 *   2. malformed syntax / reference shape      -> #ERROR!
 *   3. unsupported function name (before args) -> #NAME?
 *   4. first error met while evaluating        -> that error
 *      left to right (division by zero -> #DIV/0!, invalid reference or a
 *      dependency cycle -> #REF!)
 *
 * `evaluate` isolates failures per cell: one malformed formula never throws and
 * never stops the other cells from being computed.
 */

import {
  columnIndex,
  columnLabel,
  shiftRectOnDelete,
  shiftRectOnInsert,
} from './a1.js';

/** @typedef {{ row: number, col: number, rowAbs: boolean, colAbs: boolean, colText: string }} RefPart */
/** @typedef {'number' | 'ref' | 'range' | 'func' | 'op' | 'lparen' | 'rparen' | 'comma' | 'error'} TokenType */
/**
 * @typedef {Object} Token
 * @property {TokenType} type
 * @property {number} start
 * @property {number} end
 * @property {number} value
 * @property {string} name
 * @property {string} upper
 * @property {string} op
 * @property {RefPart | null} ref
 * @property {RefPart | null} startPart
 * @property {RefPart | null} endPart
 */
/**
 * Single-shape AST node; `kind` selects which fields are meaningful.
 *
 * @typedef {Object} Node
 * @property {string} kind
 * @property {number} value
 * @property {RefPart | null} ref
 * @property {RefPart | null} startPart
 * @property {RefPart | null} endPart
 * @property {string} upper
 * @property {string} op
 * @property {Node | null} operand
 * @property {Node | null} left
 * @property {Node | null} right
 * @property {Node[]} args
 */
/**
 * A cell value during evaluation: exactly one of `blank`, `number` (in
 * `number`), `text` (in `text`) or `error` (the error code in `text`).
 *
 * @typedef {Object} CellValue
 * @property {'blank' | 'number' | 'text' | 'error'} kind
 * @property {number} number
 * @property {string} text
 */
/** @typedef {{ rowCount: number, colCount: number }} Bounds */

const DIV0 = '#DIV/0!';
const REF = '#REF!';
const NAME = '#NAME?';
const SYNTAX = '#ERROR!';

const SUPPORTED_FUNCTIONS = new Set(['SUM', 'AVERAGE', 'COUNT', 'MIN', 'MAX']);

const REF_HEAD = /^\$?([A-Za-z]+)\$?([1-9][0-9]*)/;
const FUNC_HEAD = /^([A-Za-z][A-Za-z0-9_.]*)(?=\s*\()/;
const NUMBER_HEAD = /^(?:\d+(?:\.\d+)?|\.\d+)/;
const NUMERIC_LITERAL = /^[+-]?(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/* ------------------------------------------------------------------ *
 * Small value helpers
 * ------------------------------------------------------------------ */

/** @param {number} value @returns {CellValue} */
function numberValue(value) {
  return { kind: 'number', number: value, text: '' };
}

/** @param {string} text @returns {CellValue} */
function textValue(text) {
  return { kind: 'text', number: 0, text };
}

/** @param {string} code @returns {CellValue} */
function errorValue(code) {
  return { kind: 'error', number: 0, text: code };
}

/** @returns {CellValue} */
function blankValue() {
  return { kind: 'blank', number: 0, text: '' };
}

/** @param {CellValue} value @returns {CellValue} */
function toNumber(value) {
  if (value.kind === 'error' || value.kind === 'number') return value;
  return numberValue(0);
}

/**
 * Display text for one evaluated formula result. Numbers use 15 significant
 * digits (decision D-C6): `=1/3` -> `0.333333333333333`, `=0.1+0.2` -> `0.3`.
 *
 * @param {CellValue} value
 * @returns {string}
 */
function displayText(value) {
  if (value.kind === 'text' || value.kind === 'error') return value.text;
  if (value.kind === 'blank') return '0';
  return formatNumber(value.number);
}

/** @param {number} value @returns {string} */
function formatNumber(value) {
  if (!Number.isFinite(value)) return String(value);
  return String(Number(value.toPrecision(15)));
}

/**
 * A raw cell value is a number only when, after trimming, the whole string is a
 * signed decimal/scientific literal. This rejects `0x10`, `Infinity`, `NaN`
 * and pure whitespace, so aggregates never treat a blank or the text `TRUE` as
 * a number (decision D-C5). Exported for re-use by the validation sub-issue.
 *
 * @param {string} raw
 * @returns {boolean}
 */
export function isNumericCellValue(raw) {
  if (typeof raw !== 'string') return false;
  const text = raw.trim();
  if (text === '') return false;
  return NUMERIC_LITERAL.test(text);
}

/** @param {string} raw @returns {CellValue} */
function literalValue(raw) {
  if (isNumericCellValue(raw)) return numberValue(Number(raw.trim()));
  return textValue(raw);
}

/* ------------------------------------------------------------------ *
 * Tokenizer
 * ------------------------------------------------------------------ */

/** @param {string} ch @returns {boolean} */
function isSpace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r';
}

/** @param {string} ch @returns {boolean} */
function isLetter(ch) {
  return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
}

/** @param {TokenType} type @param {number} start @param {number} end @returns {Token} */
function makeToken(type, start, end) {
  return {
    type,
    start,
    end,
    value: 0,
    name: '',
    upper: '',
    op: '',
    ref: null,
    startPart: null,
    endPart: null,
  };
}

/**
 * Match one A1 reference at `index` (`$A$1`, `A1`, `$A1`, `A$1`).
 *
 * @param {string} body
 * @param {number} index
 * @returns {{ part: RefPart, end: number } | null}
 */
function matchRef(body, index) {
  let j = index;
  let colAbs = false;
  if (body[j] === '$') {
    colAbs = true;
    j += 1;
  }
  let letters = '';
  while (j < body.length && isLetter(body[j])) {
    letters += body[j];
    j += 1;
  }
  if (letters === '') return null;
  let rowAbs = false;
  if (body[j] === '$') {
    rowAbs = true;
    j += 1;
  }
  let digits = '';
  while (j < body.length && body[j] >= '0' && body[j] <= '9') {
    digits += body[j];
    j += 1;
  }
  if (digits === '' || digits[0] === '0') return null;
  return {
    part: { row: Number(digits) - 1, col: columnIndex(letters), rowAbs, colAbs, colText: letters },
    end: j,
  };
}

/**
 * Tokenize the body of a formula (the text after the leading `=`).
 * Returns `{ ok: false }` for anything this grammar cannot lex, which the
 * callers translate into `#ERROR!` (evaluation) or "return unchanged"
 * (reference rewriting, which is deliberately lenient).
 *
 * @param {string} body
 * @returns {{ ok: true, tokens: Token[] } | { ok: false }}
 */
function tokenize(body) {
  const tokens = [];
  const length = body.length;
  let i = 0;
  while (i < length) {
    const ch = body[i];
    if (isSpace(ch)) {
      i += 1;
      continue;
    }
    if (ch === '(' || ch === ')' || ch === ',') {
      const type = /** @type {TokenType} */ (ch === '(' ? 'lparen' : ch === ')' ? 'rparen' : 'comma');
      tokens.push(makeToken(type, i, i + 1));
      i += 1;
      continue;
    }
    if (ch === '+' || ch === '-' || ch === '*' || ch === '/') {
      const token = makeToken('op', i, i + 1);
      token.op = ch;
      tokens.push(token);
      i += 1;
      continue;
    }
    if (ch === '#') {
      // `#REF!` is a first-class token; the `!` belongs to it and must not be
      // confused with a sheet-qualified reference (`Sheet2!A1` -> #ERROR!).
      if (body.startsWith('#REF!', i)) {
        tokens.push(makeToken('error', i, i + 5));
        i += 5;
        continue;
      }
      return { ok: false };
    }
    if (ch === '$' || isLetter(ch)) {
      const ref = matchRef(body, i);
      if (ref) {
        let k = ref.end;
        while (k < length && isSpace(body[k])) k += 1;
        if (body[k] === ':') {
          let m = k + 1;
          while (m < length && isSpace(body[m])) m += 1;
          const second = matchRef(body, m);
          if (!second) return { ok: false };
          const token = makeToken('range', i, second.end);
          token.startPart = ref.part;
          token.endPart = second.part;
          tokens.push(token);
          i = second.end;
          continue;
        }
        const token = makeToken('ref', i, ref.end);
        token.ref = ref.part;
        tokens.push(token);
        i = ref.end;
        continue;
      }
      const func = FUNC_HEAD.exec(body.slice(i));
      if (func) {
        const token = makeToken('func', i, i + func[1].length);
        token.name = func[1];
        token.upper = func[1].toUpperCase();
        tokens.push(token);
        i += func[1].length;
        continue;
      }
      return { ok: false };
    }
    const number = NUMBER_HEAD.exec(body.slice(i));
    if (number) {
      const token = makeToken('number', i, i + number[0].length);
      token.value = Number(number[0]);
      tokens.push(token);
      i += number[0].length;
      continue;
    }
    return { ok: false };
  }
  return { ok: true, tokens };
}

/* ------------------------------------------------------------------ *
 * Parser
 * ------------------------------------------------------------------ */

/** @param {string} kind @returns {Node} */
function makeNode(kind) {
  return {
    kind,
    value: 0,
    ref: null,
    startPart: null,
    endPart: null,
    upper: '',
    op: '',
    operand: null,
    left: null,
    right: null,
    args: [],
  };
}

/**
 * Recursive-descent parse. Returns `null` on any syntax error (caller maps it
 * to `#ERROR!`). Function names are accepted syntactically even when unknown,
 * so `=FOO(1/0)` reaches the "unknown function wins over argument errors" rule.
 *
 * @param {Token[]} tokens
 * @returns {Node | null}
 */
function parse(tokens) {
  let pos = 0;
  const at = () => (pos < tokens.length ? tokens[pos] : null);

  /** @returns {Node | null} */
  function parseExpr() {
    let left = parseTerm();
    if (!left) return null;
    let token = at();
    while (token && token.type === 'op' && (token.op === '+' || token.op === '-')) {
      pos += 1;
      const right = parseTerm();
      if (!right) return null;
      const node = makeNode('binary');
      node.op = token.op;
      node.left = left;
      node.right = right;
      left = node;
      token = at();
    }
    return left;
  }

  /** @returns {Node | null} */
  function parseTerm() {
    let left = parseUnary();
    if (!left) return null;
    let token = at();
    while (token && token.type === 'op' && (token.op === '*' || token.op === '/')) {
      pos += 1;
      const right = parseUnary();
      if (!right) return null;
      const node = makeNode('binary');
      node.op = token.op;
      node.left = left;
      node.right = right;
      left = node;
      token = at();
    }
    return left;
  }

  /** @returns {Node | null} */
  function parseUnary() {
    const token = at();
    if (token && token.type === 'op' && token.op === '-') {
      pos += 1;
      const operand = parseUnary();
      if (!operand) return null;
      const node = makeNode('neg');
      node.operand = operand;
      return node;
    }
    return parsePrimary();
  }

  /** @returns {Node | null} */
  function parsePrimary() {
    const token = at();
    if (!token) return null;
    if (token.type === 'number') {
      pos += 1;
      const node = makeNode('number');
      node.value = token.value;
      return node;
    }
    if (token.type === 'ref') {
      pos += 1;
      const node = makeNode('ref');
      node.ref = token.ref;
      return node;
    }
    if (token.type === 'range') {
      pos += 1;
      const node = makeNode('range');
      node.startPart = token.startPart;
      node.endPart = token.endPart;
      return node;
    }
    if (token.type === 'error') {
      pos += 1;
      return makeNode('error');
    }
    if (token.type === 'lparen') {
      pos += 1;
      const inner = parseExpr();
      if (!inner) return null;
      const close = at();
      if (!close || close.type !== 'rparen') return null;
      pos += 1;
      return inner;
    }
    if (token.type === 'func') {
      pos += 1;
      const open = at();
      if (!open || open.type !== 'lparen') return null;
      pos += 1;
      const first = at();
      if (!first || first.type === 'rparen') return null;
      const args = [];
      for (;;) {
        const arg = parseExpr();
        if (!arg) return null;
        args.push(arg);
        const next = at();
        if (next && next.type === 'comma') {
          pos += 1;
          continue;
        }
        break;
      }
      const close = at();
      if (!close || close.type !== 'rparen') return null;
      pos += 1;
      const node = makeNode('call');
      node.upper = token.upper;
      node.args = args;
      return node;
    }
    return null;
  }

  const root = parseExpr();
  if (!root || pos !== tokens.length) return null;
  return root;
}

/* ------------------------------------------------------------------ *
 * Evaluation
 * ------------------------------------------------------------------ */

/**
 * Evaluate a worksheet's cells and return the text each populated cell shows.
 *
 * The map contains one entry per populated cell, keyed `"row:col"` (0-based,
 * the same key `frontend/src/lib/coordinates.ts` uses): ordinary cells map to
 * their raw text, formula cells to the calculated result or an error string.
 * Unpopulated cells are absent (the caller renders `''`). Results are neither
 * cached across calls nor persisted — `cells.raw` stays the single fact source
 * and a reload simply recomputes (decisions D-C8, D-C13).
 *
 * `bounds` is the worksheet structure used to detect a single reference that
 * points outside the sheet (`=A7` on a 6-row sheet -> `#REF!`) and to clip
 * ranges (`=SUM(B1:B1000)` sums only the cells that exist). It is optional for
 * callers that evaluate standalone fragments; the display seam always passes
 * `row_count` / `col_count`, never the import footprint (decision D-C11).
 *
 * @param {Iterable<readonly [number, number, string]>} cells
 * @param {Bounds} [bounds]
 * @returns {Map<string, string>}
 */
export function evaluate(cells, bounds) {
  const rowCount = bounds && Number.isFinite(bounds.rowCount) ? bounds.rowCount : Infinity;
  const colCount = bounds && Number.isFinite(bounds.colCount) ? bounds.colCount : Infinity;

  /** @type {Map<string, string>} */
  const raws = new Map();
  /** @type {{ row: number, col: number, raw: string }[]} */
  const entries = [];
  for (const [row, col, raw] of cells) {
    if (typeof raw !== 'string' || raw === '') continue;
    raws.set(`${row}:${col}`, raw);
    entries.push({ row, col, raw });
  }

  /** @type {Map<string, CellValue>} */
  const cache = new Map();
  const visiting = new Set();

  /** @param {number} row @param {number} col @returns {boolean} */
  const inBounds = (row, col) =>
    row >= 0 && col >= 0 && row < rowCount && col < colCount;

  /**
   * Resolve one cell through the memoized dependency graph. Recursion follows
   * references, so a cell's inputs are always computed before it (the
   * topological order); a reference back into the `visiting` set is a direct or
   * indirect cycle and yields `#REF!` for every cell on the cycle.
   *
   * @param {number} row
   * @param {number} col
   * @returns {CellValue}
   */
  function valueOf(row, col) {
    const key = `${row}:${col}`;
    const cached = cache.get(key);
    if (cached) return cached;
    if (visiting.has(key)) return errorValue(REF);
    const raw = raws.get(key);
    if (raw === undefined) return blankValue();
    if (raw.startsWith('=')) {
      visiting.add(key);
      const value = normalizeScalar(evaluateFormula(raw));
      visiting.delete(key);
      cache.set(key, value);
      return value;
    }
    return literalValue(raw);
  }

  /** @param {Node} node @returns {CellValue} */
  function evalNode(node) {
    switch (node.kind) {
      case 'number':
        return numberValue(node.value);
      case 'error':
        return errorValue(REF);
      case 'ref': {
        const ref = node.ref;
        if (!ref) return errorValue(SYNTAX);
        if (!inBounds(ref.row, ref.col)) return errorValue(REF);
        return valueOf(ref.row, ref.col);
      }
      case 'range':
        // A rectangle is not a scalar; only aggregate calls consume it.
        return errorValue(SYNTAX);
      case 'neg': {
        const operand = node.operand ? evalNode(node.operand) : errorValue(SYNTAX);
        const coerced = toNumber(operand);
        if (coerced.kind === 'error') return coerced;
        return numberValue(-coerced.number);
      }
      case 'binary': {
        const left = node.left ? evalNode(node.left) : errorValue(SYNTAX);
        if (left.kind === 'error') return left;
        const right = node.right ? evalNode(node.right) : errorValue(SYNTAX);
        if (right.kind === 'error') return right;
        const a = toNumber(left);
        if (a.kind === 'error') return a;
        const b = toNumber(right);
        if (b.kind === 'error') return b;
        if (node.op === '+') return numberValue(a.number + b.number);
        if (node.op === '-') return numberValue(a.number - b.number);
        if (node.op === '*') return numberValue(a.number * b.number);
        if (node.op === '/') {
          if (b.number === 0) return errorValue(DIV0);
          return numberValue(a.number / b.number);
        }
        return errorValue(SYNTAX);
      }
      case 'call': {
        if (!SUPPORTED_FUNCTIONS.has(node.upper)) return errorValue(NAME);
        return evalAggregate(node.upper, node.args);
      }
      default:
        return errorValue(SYNTAX);
    }
  }

  /**
   * Aggregate over every numeric value of the arguments: ranges contribute
   * only their numeric cells (blank and text cells are ignored, so empty cells
   * are never counted as zero), scalar arguments are evaluated and their
   * numeric results counted. An error anywhere in the arguments propagates
   * (decision D-C5 / assumption A-C6).
   *
   * @param {string} name
   * @param {Node[]} args
   * @returns {CellValue}
   */
  function evalAggregate(name, args) {
    let count = 0;
    let sum = 0;
    let min = Infinity;
    let max = -Infinity;

    /** @param {CellValue} value */
    function absorb(value) {
      if (value.kind !== 'number') return;
      count += 1;
      sum += value.number;
      if (value.number < min) min = value.number;
      if (value.number > max) max = value.number;
    }

    for (const arg of args) {
      if (arg.kind === 'range') {
        const start = arg.startPart;
        const end = arg.endPart;
        if (!start || !end) return errorValue(SYNTAX);
        for (const key of collectRangeKeys(start, end)) {
          const [row, col] = key.split(':').map(Number);
          const value = valueOf(row, col);
          if (value.kind === 'error') return value;
          absorb(value);
        }
      } else {
        const value = evalNode(arg);
        if (value.kind === 'error') return value;
        absorb(value);
      }
    }

    if (name === 'SUM') return numberValue(sum);
    if (name === 'COUNT') return numberValue(count);
    if (name === 'MIN') return numberValue(count === 0 ? 0 : min);
    if (name === 'MAX') return numberValue(count === 0 ? 0 : max);
    if (name === 'AVERAGE') return count === 0 ? errorValue(DIV0) : numberValue(sum / count);
    return errorValue(NAME);
  }

  /**
   * Populated keys inside a range, clipped to the worksheet structure and
   * ordered row-major. Empty positions are skipped because they contribute
   * nothing to an aggregate (decision D-C11 clipping + D-C5 empty semantics).
   *
   * @param {RefPart} a
   * @param {RefPart} b
   * @returns {string[]}
   */
  function collectRangeKeys(a, b) {
    const r1 = Math.min(a.row, b.row);
    const r2 = Math.max(a.row, b.row);
    const c1 = Math.min(a.col, b.col);
    const c2 = Math.max(a.col, b.col);
    const keys = [];
    for (const entry of entries) {
      if (entry.row < r1 || entry.row > r2 || entry.col < c1 || entry.col > c2) continue;
      if (!inBounds(entry.row, entry.col)) continue;
      keys.push(`${entry.row}:${entry.col}`);
    }
    keys.sort((left, right) => {
      const [lr, lc] = left.split(':').map(Number);
      const [rr, rc] = right.split(':').map(Number);
      return lr - rr || lc - rc;
    });
    return keys;
  }

  /**
   * Parse and evaluate one formula. Any lexer/parser failure becomes `#ERROR!`;
   * nothing throws (decision D-C2 step 1/2 and per-cell isolation).
   *
   * @param {string} raw
   * @returns {CellValue}
   */
  function evaluateFormula(raw) {
    const lexed = tokenize(raw.slice(1));
    if (!lexed.ok) return errorValue(SYNTAX);
    const ast = parse(lexed.tokens);
    if (!ast) return errorValue(SYNTAX);
    return evalNode(ast);
  }

  /** @type {Map<string, string>} */
  const result = new Map();
  for (const entry of entries) {
    const key = `${entry.row}:${entry.col}`;
    if (entry.raw.startsWith('=')) {
      result.set(key, displayText(valueOf(entry.row, entry.col)));
    } else {
      result.set(key, entry.raw);
    }
  }
  return result;
}

/**
 * A bare reference to an empty cell reads as 0 at the top level (`=A1` with an
 * empty A1 shows `0`), while `=A1` with text in A1 passes that text through.
 *
 * @param {CellValue} value
 * @returns {CellValue}
 */
function normalizeScalar(value) {
  return value.kind === 'blank' ? numberValue(0) : value;
}

/* ------------------------------------------------------------------ *
 * Reference rewriting
 * ------------------------------------------------------------------ */

/**
 * Re-emit one reference part with its original `$` markers and column-letter
 * case preserved (decision D-C4: the formula bar shows the user's text, so a
 * rewrite must not silently reformat it).
 *
 * @param {number} row
 * @param {number} col
 * @param {RefPart} original
 * @returns {string}
 */
function formatRefPart(row, col, original) {
  const rawLabel = col === original.col ? original.colText : columnLabel(col);
  const label = matchLetterCase(rawLabel, original.colText);
  return `${original.colAbs ? '$' : ''}${label}${original.rowAbs ? '$' : ''}${row + 1}`;
}

/**
 * @param {string} label
 * @param {string} original
 * @returns {string}
 */
function matchLetterCase(label, original) {
  const lower = original === original.toLowerCase() && original !== original.toUpperCase();
  return lower ? label.toLowerCase() : label.toUpperCase();
}

/**
 * Apply a token-level mapping to every reference in a formula, splicing the
 * replacements into the original text so operators, whitespace, function-name
 * case and `$` markers all survive untouched. Inputs the tokenizer cannot lex
 * are returned unchanged (deliberate leniency, decision D-C4).
 *
 * @param {string} formula
 * @param {(token: Token, original: string) => { collapse: boolean, text: string }} mapToken
 * @returns {string}
 */
function rewriteFormula(formula, mapToken) {
  if (typeof formula !== 'string' || !formula.startsWith('=')) return formula;
  const body = formula.slice(1);
  const lexed = tokenize(body);
  if (!lexed.ok) return formula;
  let out = '';
  let cursor = 0;
  for (const token of lexed.tokens) {
    if (token.type !== 'ref' && token.type !== 'range') continue;
    const mapped = mapToken(token, body.slice(token.start, token.end));
    if (mapped.collapse) return '=#REF!';
    out += body.slice(cursor, token.start) + mapped.text;
    cursor = token.end;
  }
  out += body.slice(cursor);
  return `=${out}`;
}

/**
 * Rewrite a formula for a copy to another cell (REQ-4-1-2). Relative
 * components move by `(dRow, dCol)`; `$`-marked components stay.
 *
 * If the offset pushes **any** relative reference out of the target worksheet,
 * the whole formula collapses to the literal `=#REF!` (decision D-C3): the
 * requirement gives that exact string for the formula bar, and it holds for
 * both single- and multi-reference formulas. Pure absolute references cannot
 * move and therefore never trigger the collapse.
 *
 * `bounds` is the **target** worksheet's structure. A caller that first grows
 * the worksheet through the structure endpoint must pass the grown dimensions
 * (decision D-C3); the import footprint is never used here (decision D-C11).
 * This is a pure function: the input string is not modified.
 *
 * @param {string} formula
 * @param {number} dRow
 * @param {number} dCol
 * @param {Bounds} [bounds]
 * @returns {string}
 */
export function rewriteRefsOnCopy(formula, dRow, dCol, bounds) {
  const rowCount = bounds && Number.isFinite(bounds.rowCount) ? bounds.rowCount : Infinity;
  const colCount = bounds && Number.isFinite(bounds.colCount) ? bounds.colCount : Infinity;

  /**
   * @param {RefPart} part
   * @returns {{ row: number, col: number, outside: boolean }}
   */
  const mapPart = (part) => {
    const row = part.row + (part.rowAbs ? 0 : dRow);
    const col = part.col + (part.colAbs ? 0 : dCol);
    const relative = !part.rowAbs || !part.colAbs;
    const outside = relative && (row < 0 || col < 0 || row >= rowCount || col >= colCount);
    return { row, col, outside };
  };

  return rewriteFormula(formula, (token) => {
    if (token.type === 'ref') {
      const part = token.ref;
      if (!part) return { collapse: true, text: '' };
      const mapped = mapPart(part);
      if (mapped.outside) return { collapse: true, text: '' };
      return { collapse: false, text: formatRefPart(mapped.row, mapped.col, part) };
    }
    const start = token.startPart;
    const end = token.endPart;
    if (!start || !end) return { collapse: true, text: '' };
    const mappedStart = mapPart(start);
    const mappedEnd = mapPart(end);
    if (mappedStart.outside || mappedEnd.outside) return { collapse: true, text: '' };
    return {
      collapse: false,
      text: `${formatRefPart(mappedStart.row, mappedStart.col, start)}:${formatRefPart(
        mappedEnd.row,
        mappedEnd.col,
        end,
      )}`,
    };
  });
}

/**
 * Rewrite a formula for a structural row/column insert or delete (REQ-4-2-1,
 * REQ-2-2-1/2-2-2). The coordinate mapping is the shared B-3 primitive in
 * `shared/a1.js`, so formulas and stored ranges move together:
 *
 * - insert `count` slots at `index`: references at or after it move by `count`;
 *   a range that receives the insertion expands, one entirely above it does not
 *   move. **Absolute references move too** — the requirement says all formula
 *   references shift (decision D-C4 / C-1b).
 * - delete at `index`: a reference to exactly that slot becomes a `#REF!`
 *   token, later references move up by one, an intersecting range shrinks
 *   (keeping its `:`), and a range that collapses becomes `#REF!`.
 *
 * Non-formula values and formulas the tokenizer cannot lex are returned
 * unchanged.
 *
 * @param {string} formula
 * @param {'row' | 'column'} axis
 * @param {number} index
 * @param {number} count
 * @param {boolean} [isDelete]
 * @returns {string}
 */
export function rewriteRefsOnInsertDelete(formula, axis, index, count, isDelete) {
  const remove = isDelete === true;

  /**
   * @param {RefPart} a
   * @param {RefPart} b
   * @returns {{ r1: number, c1: number, r2: number, c2: number }}
   */
  const rectOf = (a, b) => {
    const rows = a.row <= b.row ? [a.row, b.row] : [b.row, a.row];
    const cols = a.col <= b.col ? [a.col, b.col] : [b.col, a.col];
    return { r1: rows[0], c1: cols[0], r2: rows[1], c2: cols[1] };
  };

  /** @param {{ r1: number, c1: number, r2: number, c2: number }} rect */
  const mapRect = (rect) =>
    remove ? shiftRectOnDelete(rect, axis, index) : shiftRectOnInsert(rect, axis, index, count);

  return rewriteFormula(formula, (token, original) => {
    if (token.type === 'ref') {
      const part = token.ref;
      if (!part) return { collapse: false, text: REF };
      const result = mapRect({ r1: part.row, c1: part.col, r2: part.row, c2: part.col });
      if (result === null) return { collapse: false, text: REF };
      if (!result.changed) return { collapse: false, text: original };
      return {
        collapse: false,
        text: formatRefPart(result.rect.r1, result.rect.c1, part),
      };
    }
    const start = token.startPart;
    const end = token.endPart;
    if (!start || !end) return { collapse: false, text: REF };
    const result = mapRect(rectOf(start, end));
    if (result === null) return { collapse: false, text: REF };
    if (!result.changed) return { collapse: false, text: original };
    return {
      collapse: false,
      text: `${formatRefPart(result.rect.r1, result.rect.c1, start)}:${formatRefPart(
        result.rect.r2,
        result.rect.c2,
        end,
      )}`,
    };
  });
}

