  it('keeps absolute components unchanged, with mixed references', () => {
    expect(rewriteRefsOnCopy('=$A$1', 1, 1, BOUNDS)).toBe('=$A$1');
    expect(rewriteRefsOnCopy('=$A1+B$2', 1, 1, BOUNDS)).toBe('=$A2+C$2');
    expect(rewriteRefsOnCopy('=A$1', 2, 2, BOUNDS)).toBe('=C$1');
  });

  it('preserves the original column-letter case', () => {
    expect(rewriteRefsOnCopy('=a1', 1, 1, BOUNDS)).toBe('=b2');
    expect(rewriteRefsOnCopy('=sum(a1:b2)', 1, 0, BOUNDS)).toBe('=sum(a1:b2)');
  });

  it('collapses the whole formula to =#REF! when a relative reference leaves the sheet', () => {
    // `=A1+B1` copied from C1 to B1: A1's relative column goes out of bounds.
    expect(rewriteRefsOnCopy('=A1+B1', 0, -1, BOUNDS)).toBe('=#REF!');
    // Upper bound: `=A6` one row below the last row of a 6-row sheet.
    expect(rewriteRefsOnCopy('=A6', 1, 0, BOUNDS)).toBe('=#REF!');
    expect(rewriteRefsOnCopy('=SUM(A5:A6)', 1, 0, BOUNDS)).toBe('=#REF!');
    expect(rewriteRefsOnCopy('=A1', 0, -1, BOUNDS)).toBe('=#REF!');
  });

  it('never collapses a formula whose references are all absolute', () => {
    // `$AA$1` is outside a 26-column sheet, but copying cannot move it and the
    // requirement's out-of-bounds rule only concerns relative references.
    expect(rewriteRefsOnCopy('=$AA$1', 0, 0, BOUNDS)).toBe('=$AA$1');
    expect(rewriteRefsOnCopy('=$A$1+$B$2', 5, 5, BOUNDS)).toBe('=$A$1+$B$2');
  });

  it('is a pure function: the input is never modified', () => {
    const formula = '=A1+B2';
    expect(rewriteRefsOnCopy(formula, 1, 1, BOUNDS)).toBe('=B2+C3');
    expect(formula).toBe('=A1+B2');
  });

  it('returns non-formulas and unparseable formulas unchanged', () => {
    expect(rewriteRefsOnCopy('plain text', 1, 1, BOUNDS)).toBe('plain text');
    expect(rewriteRefsOnCopy('=A0', 1, 1, BOUNDS)).toBe('=A0');
    expect(rewriteRefsOnCopy('=Sheet2!A1', 1, 1, BOUNDS)).toBe('=Sheet2!A1');
  });
});

describe('5. structural reference rewriting', () => {
  it('shifts references at or after an inserted row/column', () => {
    expect(rewriteRefsOnInsertDelete('=A1', 'row', 0, 1)).toBe('=A2');
    expect(rewriteRefsOnInsertDelete('=A1', 'row', 5, 1)).toBe('=A1');
    expect(rewriteRefsOnInsertDelete('=B2', 'column', 0, 1)).toBe('=C2');
    expect(rewriteRefsOnInsertDelete('=B2', 'column', 3, 1)).toBe('=B2');
  });

  it('moves absolute references too (the requirement shifts all formula references)', () => {
    expect(rewriteRefsOnInsertDelete('=$A$1', 'row', 0, 1)).toBe('=$A$2');
    expect(rewriteRefsOnInsertDelete('=$A$1+B2', 'column', 0, 2)).toBe('=$C$1+D2');
  });

  it('shifts an entire range above the insertion and expands one that receives it', () => {
    expect(rewriteRefsOnInsertDelete('=SUM(A3:A4)', 'row', 1, 1)).toBe('=SUM(A4:A5)');
    expect(rewriteRefsOnInsertDelete('=SUM(A3:A4)', 'row', 3, 1)).toBe('=SUM(A3:A5)');
    expect(rewriteRefsOnInsertDelete('=SUM(A3:A4)', 'row', 5, 1)).toBe('=SUM(A3:A4)');
  });

  it('rewrites deletions: exact hits become #REF!, later references move up', () => {
    expect(rewriteRefsOnInsertDelete('=C3', 'row', 2, 1, true)).toBe('=#REF!');
    expect(rewriteRefsOnInsertDelete('=C5', 'row', 2, 1, true)).toBe('=C4');
    expect(rewriteRefsOnInsertDelete('=A1', 'row', 2, 1, true)).toBe('=A1');
  });

  it('shrinks an intersecting range keeping its colon, and collapses it at one cell', () => {
    expect(rewriteRefsOnInsertDelete('=SUM(A3:A4)', 'row', 2, 1, true)).toBe('=SUM(A3:A3)');
    expect(rewriteRefsOnInsertDelete('=SUM(A5:A6)', 'row', 2, 1, true)).toBe('=SUM(A4:A5)');
    expect(rewriteRefsOnInsertDelete('=SUM(A1:A2)', 'row', 2, 1, true)).toBe('=SUM(A1:A2)');
    expect(rewriteRefsOnInsertDelete('=SUM(A3:A3)', 'row', 2, 1, true)).toBe('=SUM(#REF!)');
  });

  it('preserves $ markers, range colons and the original letter case', () => {
    expect(rewriteRefsOnInsertDelete('=sum($a$3:$b$4)', 'row', 2, 1, true)).toBe(
      '=sum($a$3:$b$3)',
    );
    expect(rewriteRefsOnInsertDelete('=sum(b2:b6)', 'column', 0, 1)).toBe('=sum(c2:c6)');
  });

  it('rewrites every reference in a multi-reference formula', () => {
    expect(rewriteRefsOnInsertDelete('=A1+B2', 'row', 0, 1)).toBe('=A2+B3');
    expect(rewriteRefsOnInsertDelete('=#REF!+A1', 'row', 0, 1)).toBe('=#REF!+A2');
  });

  it('returns non-formulas and unparseable formulas unchanged', () => {
    expect(rewriteRefsOnInsertDelete('plain', 'row', 0, 1)).toBe('plain');
    expect(rewriteRefsOnInsertDelete('=A0', 'row', 0, 1)).toBe('=A0');
    expect(rewriteRefsOnInsertDelete('=Sheet2!A1', 'row', 0, 1)).toBe('=Sheet2!A1');
  });
});

describe('6. aggregation and empty/text semantics', () => {
  const mixed: Cells = [
    [0, 0, 'East'],
    [0, 1, '3'],
    [1, 0, '2'],
  ];
  // Range A1:C3 covers text (East), numbers (3, 2) and empty cells.
  const aggregate = (formula: string) => place(formula, '0:4', mixed);

  it('only aggregates numeric cells, ignoring empty and text cells', () => {
    expect(aggregate('=SUM(A1:C3)')).toBe('5');
    expect(aggregate('=COUNT(A1:C3)')).toBe('2');
    expect(aggregate('=AVERAGE(A1:C3)')).toBe('2.5');
    expect(aggregate('=MIN(A1:C3)')).toBe('2');
    expect(aggregate('=MAX(A1:C3)')).toBe('3');
  });

  it('treats an empty cell as absent, never as zero', () => {
    const sources: Cells = [[1, 0, '5']];
    expect(place('=AVERAGE(A1:A2)', '0:2', sources)).toBe('5');
    expect(place('=COUNT(A1:A2)', '0:2', sources)).toBe('1');
    expect(place('=SUM(A1:A2)', '0:2', sources)).toBe('5');
  });

  it('returns the empty-aggregate values for a range with no numeric cell', () => {
    expect(result('=SUM(A1:A3)')).toBe('0');
    expect(result('=COUNT(A1:A3)')).toBe('0');
    expect(result('=MIN(A1:A3)')).toBe('0');
    expect(result('=MAX(A1:A3)')).toBe('0');
    expect(result('=AVERAGE(A1:A3)')).toBe('#DIV/0!');
  });

  it('accepts comma-separated scalar arguments', () => {
    expect(result('=SUM(1, 2, 3)')).toBe('6');
    expect(place('=SUM(A1, B1, 3)', '0:2', [[0, 0, '2'], [0, 1, '4']])).toBe('9');
  });

  it('rejects unsupported string literals as malformed expressions', () => {
    expect(result('=COUNT(1, "text")')).toBe('#ERROR!');
  });

  it('produces the seed aggregates over B2:B6 and A2:A6', () => {
    expect(at([...SEED, [0, 4, '=SUM(B2:B6)']], '0:4')).toBe('2700');
    expect(at([...SEED, [0, 4, '=AVERAGE(B2:B6)']], '0:4')).toBe('900');
    expect(at([...SEED, [0, 4, '=COUNT(B2:B6)']], '0:4')).toBe('3');
    expect(at([...SEED, [0, 4, '=MIN(B2:B6)']], '0:4')).toBe('700');
    expect(at([...SEED, [0, 4, '=MAX(B2:B6)']], '0:4')).toBe('1200');
    expect(at([...SEED, [0, 4, '=SUM(A2:A6)']], '0:4')).toBe('0');
    expect(at([...SEED, [0, 4, '=AVERAGE(A2:A6)']], '0:4')).toBe('#DIV/0!');
  });
});

describe('7. error values, precedence, cycles and isolation', () => {
  it('reports division by zero', () => {
    expect(result('=1/0')).toBe('#DIV/0!');
    expect(result('=0/0')).toBe('#DIV/0!');
    expect(result('=5/(2-2)')).toBe('#DIV/0!');
  });

  it('reports unsupported function names before evaluating their arguments', () => {
    expect(result('=FOO(1)')).toBe('#NAME?');
    expect(result('=IF(1,2,3)')).toBe('#NAME?');
    expect(result('=FOO(1/0)')).toBe('#NAME?');
  });

  it('reports malformed expressions and reference shapes as #ERROR!', () => {
    for (const formula of [
      '=(1+2',
      '=1+',
      '=',
      '=A0',
      '=Sheet2!A1',
      '=A1:B2:C3',
      '=SUM()',
      '=1 2',
      '=#DIV/0!',
    ]) {
      expect(result(formula)).toBe('#ERROR!');
    }
  });

  it('returns the first error met left to right while evaluating', () => {
    expect(result('=1/0+A7')).toBe('#DIV/0!');
    expect(result('=A7+1/0')).toBe('#REF!');
  });

  it('reports invalid references and cycles as #REF!', () => {
    expect(result('=A7')).toBe('#REF!');
    expect(result('=#REF!')).toBe('#REF!');
    expect(result('=#REF!+A1')).toBe('#REF!');
    expect(result('=SUM(#REF!)')).toBe('#REF!');
  });

  it('detects a direct cycle', () => {
    const cells: Cells = [[0, 0, '=B1'], [0, 1, '=A1']];
    expect(display(cells).get('0:0')).toBe('#REF!');
    expect(display(cells).get('0:1')).toBe('#REF!');
  });

  it('detects an indirect three-cell cycle', () => {
    const cells: Cells = [[0, 0, '=B1'], [0, 1, '=C1'], [0, 2, '=A1']];
    const values = display(cells);
    expect(values.get('0:0')).toBe('#REF!');
    expect(values.get('0:1')).toBe('#REF!');
    expect(values.get('0:2')).toBe('#REF!');
  });

  it('detects a self-referencing range', () => {
    expect(result('=SUM(A1:A3)')).toBe('#REF!');
  });

  it('propagates a cycle error to dependents outside the cycle', () => {
    const cells: Cells = [[0, 0, '=B1'], [0, 1, '=A1'], [0, 3, '=A1+1']];
    expect(display(cells).get('0:3')).toBe('#REF!');
  });

  it('propagates an error cell through an aggregate instead of skipping it', () => {
    const cells: Cells = [[0, 0, '=1/0'], [0, 2, '=SUM(A1:A2)']];
    expect(display(cells).get('0:2')).toBe('#DIV/0!');
  });

  it('isolates one malformed cell from every other cell', () => {
    const cells: Cells = [[0, 0, '=(1+2'], [0, 1, '=1+1'], [0, 2, '=B1+1']];
    const values = display(cells);
    expect(values.get('0:0')).toBe('#ERROR!');
    expect(values.get('0:1')).toBe('2');
    expect(values.get('0:2')).toBe('3');
  });

  it('recovers from a cycle when the source changes (no stale cache)', () => {
    const broken: Cells = [[0, 0, '=B1'], [0, 1, '=A1']];
    expect(display(broken).get('0:0')).toBe('#REF!');
    const fixed: Cells = [[0, 0, '=B1'], [0, 1, '3']];
    expect(display(fixed).get('0:0')).toBe('3');
  });
});

describe('7b. numeric-cell syntax and bare-reference pass-through', () => {
  it('recognises exactly signed decimal/scientific literals', () => {
    for (const raw of ['0', '7', '-7', '+7', '2.5', '.5', '1e3', '1E-3', ' 5 ']) {
      expect(isNumericCellValue(raw)).toBe(true);
    }
    for (const raw of [
      '',
      '   ',
      '0x10',
      'Infinity',
      '-Infinity',
      'NaN',
      'TRUE',
      'East',
      '1,000',
      '=1+1',
    ]) {
      expect(isNumericCellValue(raw)).toBe(false);
    }
  });

  it('does not count blank or boolean-looking text cells', () => {
    const sources: Cells = [[0, 1, 'TRUE']];
    expect(result('=COUNT(A1:B1)', sources)).toBe('0');
    expect(result('=SUM(A1:B1)', sources)).toBe('0');
  });

  it('treats the text Infinity as text, never as a number', () => {
    const sources: Cells = [[0, 0, 'Infinity']];
    expect(place('=COUNT(A1)', '0:2', sources)).toBe('0');
    expect(at(sources, '0:0')).toBe('Infinity');
  });

  it('passes a bare reference to text through and reads an empty cell as 0', () => {
    expect(place('=A1', '0:2', [[0, 0, 'East']])).toBe('East');
    expect(result('=A1')).toBe('0');
  });

  it('coerces text and empty cells to 0 only inside arithmetic', () => {
    expect(place('=A1+1', '0:2', [[0, 0, 'East']])).toBe('1');
    expect(result('=A1+1')).toBe('1');
  });
});

describe('8. numeric display format (15 significant digits)', () => {
  it.each([
    ['=1/3', '0.333333333333333'],
    ['=2/3', '0.666666666666667'],
    ['=0.1+0.2', '0.3'],
    ['=10/2', '5'],
    ['=2.5*2', '5'],
    ['=1e308*10', 'Infinity'],
  ])('%s -> %s', (formula, expected) => {
    expect(result(formula)).toBe(expected);
  });

  it('never shows a negative zero', () => {
    expect(result('=-0')).toBe('0');
    expect(result('=0*-1')).toBe('0');
  });
});

describe('9. evaluate output shape and bounds', () => {
  it('maps ordinary cells to raw text, formulas to results, and omits empty cells', () => {
    const cells: Cells = [
      [0, 0, 'Region'],
      [0, 1, '007'],
      [1, 0, '=A1'],
      [1, 1, '=1/0'],
    ];
    const values = evaluate(cells, BOUNDS);
    expect(values.get('0:0')).toBe('Region');
    // An ordinary numeric-looking cell still shows its raw text...
    expect(values.get('0:1')).toBe('007');
    expect(values.get('1:0')).toBe('Region');
    expect(values.get('1:1')).toBe('#DIV/0!');
    expect(values.has('5:25')).toBe(false);
    expect(values.size).toBe(4);
  });

  it('evaluates formulas without bounds as standalone fragments', () => {
    expect(new Map(evaluate([[0, 0, '=1+2*3']])).get('0:0')).toBe('7');
    // Without structural bounds there is no upper-bound check.
    expect(new Map(evaluate([[0, 0, '=A7']])).get('0:0')).toBe('0');
  });

  it('clips a range to the structure instead of failing', () => {
    expect(result('=SUM(B1:B1000)', [[0, 1, '2'], [1, 1, '3']])).toBe('5');
  });
});

import { describe, expect, it } from 'vitest';
import type { WorksheetSnapshot } from '../../../shared/types';
import { worksheetDisplayValues } from './cellDisplay';

function sheet(cells: [number, number, string][]): WorksheetSnapshot {
  return {
    id: 'ws-1',
    name: 'Sheet1',
    position: 0,
    isActive: true,
    rowCount: 6,
    colCount: 26,
    minRows: 0,
    minCols: 0,
    cells,
    lastSelection: null,
    validations: [],
    filters: [],
    pivots: [],
  };
}

/**
 * D-A8 / contract increment A-3: the grid and the CSV export share this seam.
 * Sub-issue C (Issue #5 decision D-C8) replaced the interim identity
 * implementation with the formula engine, so a formula cell now displays (and
 * exports) its calculated result or error string while the formula bar and the
 * inline editor keep reading `cells` raw.
 */
describe('worksheetDisplayValues', () => {
  it('returns the raw text for populated non-formula cells', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, 'Region'], [1, 1, '1200']]));
    expect(display(0, 0)).toBe('Region');
    expect(display(1, 1)).toBe('1200');
  });

  it('returns an empty string for cells that have no stored value', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, 'Region']]));
    expect(display(5, 25)).toBe('');
    expect(display(0, 1)).toBe('');
  });

  it('returns the calculated result for a formula cell (transition flipped by C)', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, '=1+1']]));
    expect(display(0, 0)).toBe('2');
  });

  it('calculates formulas from the current source cells', () => {
    const display = worksheetDisplayValues(
      sheet([[0, 0, '2'], [0, 1, '3'], [0, 2, '=A1+B1'], [0, 3, '=C1*2']]),
    );
    expect(display(0, 2)).toBe('5');
    expect(display(0, 3)).toBe('10');
  });

  it('returns the error string for an error cell, through the same seam as the export', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, '=1/0']]));
    expect(display(0, 0)).toBe('#DIV/0!');
  });

  it('reads an empty referenced cell as 0 and flags an out-of-structure reference', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, '=Z1+1'], [0, 1, '=A7']]));
    expect(display(0, 0)).toBe('1');
    expect(display(0, 1)).toBe('#REF!');
  });
});

