import fs from 'node:fs';
import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';

/**
 * Sub-issue C acceptance (Issue #5 REQ-4-1-1 / 4-1-2 / 4-2-1 / 4-2-2).
 *
 * Runs against the production shape (built frontend served by the backend on
 * one port, throwaway SQLite file) via `bash checks/run-e2e.sh`, and drives the
 * UI exclusively through accessible names. This suite is also the runtime gate
 * for the shared `shared/formula.js` module: the frontend program does not
 * `checkJs` it, so only a real browser execution exercises it (Issue #1 thread 1
 * comment #118/#119).
 *
 * Every workbook is created through the UI, so no test depends on another
 * suite's edits to the seeded `Q3 Sales` workbook. Grid cells are located with
 * `exact: true` (contract v1.2 location discipline).
 *
 * REQ-4-1-2's end-to-end copy/paste scenario is sub-issue D's delivery; this PR
 * covers the rewrite API by unit test only.
 */

async function gotoHome(page: Page): Promise<void> {
  await page.goto('/');
  await expect(page.getByRole('link', { name: 'Q3 Sales', exact: true })).toBeVisible();
}

async function createWorkbook(page: Page, name: string): Promise<void> {
  await gotoHome(page);
  await page.getByRole('button', { name: 'New blank workbook' }).click();
  await expect(page).toHaveURL(/\/new$/);
  await page.getByLabel('Workbook name').fill(name);
  await page.getByRole('button', { name: 'Create' }).click();
  await expect(page).toHaveURL(/\/workbook\/.+/);
  await expect(page.getByRole('grid', { name: 'Worksheet grid' })).toBeVisible();
}

async function cellText(page: Page, coordinate: string): Promise<string> {
  return (await page.getByRole('gridcell', { name: coordinate, exact: true }).textContent()) ?? '';
}

/** Exact text comparison with retries (cells fill in after the write round-trip). */
async function expectCellText(page: Page, coordinate: string, text: string): Promise<void> {
  await expect
    .poll(() => cellText(page, coordinate), {
      message: `gridcell ${coordinate} should contain ${JSON.stringify(text)}`,
    })
    .toBe(text);
}

async function selectCell(page: Page, coordinate: string): Promise<void> {
  await page.getByRole('gridcell', { name: coordinate, exact: true }).click();
  await expect(page.getByRole('textbox', { name: 'Name box' })).toHaveValue(coordinate);
}

async function typeFormulaBar(page: Page, coordinate: string, value: string): Promise<void> {
  await selectCell(page, coordinate);
  const formulaBar = page.getByRole('textbox', { name: 'Formula bar' });
  await formulaBar.fill(value);
  await formulaBar.press('Enter');
}

/** Inline edit through the grid ("Edit <coordinate>" text box). */
async function editCell(page: Page, coordinate: string, value: string): Promise<void> {
  await page.getByRole('gridcell', { name: coordinate, exact: true }).dblclick();
  const editor = page.getByRole('textbox', { name: `Edit ${coordinate}` });
  await expect(editor).toBeVisible();
  await editor.fill(value);
  await editor.press('Enter');
  await expect(editor).toHaveCount(0);
}

async function expectFormulaBar(page: Page, coordinate: string, value: string): Promise<void> {
  await selectCell(page, coordinate);
  await expect(page.getByRole('textbox', { name: 'Formula bar' })).toHaveValue(value);
}

async function exportCsv(page: Page): Promise<string> {
  const [download] = await Promise.all([
    page.waitForEvent('download'),
    page.getByRole('button', { name: 'Export CSV' }).click(),
  ]);
  const path = await download.path();
  if (!path) throw new Error('download has no local path');
  return fs.readFileSync(path, 'utf8');
}

test.describe('REQ-4-1-1 formula input, grid result and formula bar text', () => {
  test('shows calculated results in the grid and the submitted formula in the formula bar, across a reload', async ({
    page,
  }) => {
    await createWorkbook(page, 'C results and formula bar');

    // Inline editing path for plain values and formulas.
    await editCell(page, 'A1', '2');
    await editCell(page, 'B1', '3');
    await editCell(page, 'C1', '=A1+B1');
    await editCell(page, 'D1', '=C1*2');
    await expectCellText(page, 'C1', '5');
    await expectCellText(page, 'D1', '10');
    await expectFormulaBar(page, 'C1', '=A1+B1');

    // Formula-bar path for the supported functions.
    await typeFormulaBar(page, 'E1', '=SUM(A1:B1)');
    await typeFormulaBar(page, 'F1', '=AVERAGE(A1:B1)');
    await typeFormulaBar(page, 'G1', '=COUNT(A1:B1)');
    await typeFormulaBar(page, 'H1', '=MIN(A1:B1)');
    await typeFormulaBar(page, 'I1', '=MAX(A1:B1)');
    await expectCellText(page, 'E1', '5');
