    await page.reload();
    await expect(page.getByRole('grid', { name: 'Worksheet grid' })).toBeVisible();
    await expectCellText(page, 'C1', '5');
    await expectCellText(page, 'D1', '10');
    await expectCellText(page, 'I1', '3');
    await expectFormulaBar(page, 'C1', '=A1+B1');
