});

test.describe('REQ-4-2-1 dependency recalculation', () => {
  test('recalculates direct and indirect dependents when a source value changes', async ({ page }) => {
    await createWorkbook(page, 'C dependency chain');
    await editCell(page, 'A1', '2');
    await editCell(page, 'B1', '3');
    await editCell(page, 'C1', '=A1+B1');
    await editCell(page, 'D1', '=C1*2');
    await expectCellText(page, 'C1', '5');
    await expectCellText(page, 'D1', '10');

    await editCell(page, 'B1', '4');
    await expectCellText(page, 'C1', '6');
    await expectCellText(page, 'D1', '12');
    await expectFormulaBar(page, 'C1', '=A1+B1');
  });

  test('keeps formulas scoped to their own worksheet', async ({ page }) => {
    await createWorkbook(page, 'C worksheet isolation');
    await editCell(page, 'A1', '2');

    await page.getByRole('button', { name: 'Add worksheet' }).click();
