function parse(tokens) {
  let pos = 0;
  /**
   * Recursion budget shared by every descent step. A pathologically deep
   * expression (thousands of nested parentheses or unary minuses) must fail as
   * `#ERROR!` instead of overflowing the call stack, because a throw would
   * break the per-cell isolation D-C2/REQ-4-2-2 requires.
   */
  const MAX_PARSE_DEPTH = 256;
  let depth = 0;
  const at = () => (pos < tokens.length ? tokens[pos] : null);

  /** @returns {Node | null} */
  function parseExpr() {
    depth += 1;
    try {
      if (depth > MAX_PARSE_DEPTH) return null;
      let left = parseTerm();
      if (!left) return null;
      let token = at();
      while (token && token.type === 'op' && (token.op === '+' || token.op === '-')) {
        pos += 1;
        const right = parseTerm();
        if (!right) return null;
        const node = makeNode('binary');
        node.op = token.op;
        node.left = left;
        node.right = right;
        left = node;
        token = at();
      }
      return left;
    } finally {
      depth -= 1;
    }
  }

