/**
 * Parse and evaluate one formula. Any lexer/parser failure becomes `#ERROR!`;
 * nothing throws (decision D-C2 step 1/2 and per-cell isolation). The outer
 * `try` is the last-resort guarantee: the parser has its own recursion budget
 * (see `parse`), and anything unexpected (for example a stack overflow on a
 * deliberately hostile input) is reported for that cell alone instead of
 * failing the whole worksheet.
 *
 * @param {string} raw
 * @returns {CellValue}
 */
function evaluateFormula(raw) {
