it('isolates one malformed cell from every other cell', () => {
  const cells: Cells = [[0, 0, '=(1+2'], [0, 1, '=1+1'], [0, 2, '=B1+1']];
  const values = display(cells);
  expect(values.get('0:0')).toBe('#ERROR!');
  expect(values.get('0:1')).toBe('2');
  expect(values.get('0:2')).toBe('3');
});

it('never throws on pathologically deep input and keeps other cells working', () => {
  // Issue-side review #143 §1 / #147 §3: without a recursion budget a deep
  // expression overflowed the stack and failed the whole worksheet, breaking
  // D-C2's "no cell may make evaluation throw" / REQ-4-2-2 isolation.
  const deepParens = `=${'('.repeat(5000)}1${')'.repeat(5000)}`;
  const deepUnary = `=${'-'.repeat(5000)}1`;
  const cells: Cells = [
    [0, 0, deepParens],
    [0, 1, deepUnary],
    [0, 2, '=1+1'],
    [0, 3, '=A1'],
  ];
  const values = display(cells);
  expect(values.get('0:0')).toBe('#ERROR!');
  expect(values.get('0:1')).toBe('#ERROR!');
  expect(values.get('0:2')).toBe('2');
  expect(values.get('0:3')).toBe('#ERROR!');
});

